// 生成表单HTML节点 - 完整代码（包含邮箱字段）
// 返回HTML表单页面（修改了提交URL）
const htmlForm = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>个性化健康管理方案 - 信息采集</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            padding: 20px;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .container {
            background: white;
            border-radius: 16px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.2);
            max-width: 800px;
            width: 100%;
            padding: 40px;
            margin: 20px;
        }

        .header {
            text-align: center;
            margin-bottom: 40px;
            padding-bottom: 20px;
            border-bottom: 3px solid #4CAF50;
        }

        .header h1 {
            color: #4CAF50;
            font-size: 2.5em;
            margin-bottom: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
        }

        .header p {
            color: #666;
            font-size: 1.1em;
        }

        .form-section {
            margin-bottom: 30px;
        }

        .section-title {
            font-size: 1.3em;
            color: #4CAF50;
            margin-bottom: 20px;
            padding-bottom: 10px;
            border-bottom: 2px solid #e0e0e0;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .form-group {
            margin-bottom: 20px;
        }

        .form-group label {
            display: block;
            margin-bottom: 8px;
            color: #333;
            font-weight: 500;
            font-size: 0.95em;
        }

        .form-group input,
        .form-group select {
            width: 100%;
            padding: 12px 16px;
            border: 2px solid #e0e0e0;
            border-radius: 8px;
            font-size: 1em;
            transition: all 0.3s ease;
            background: #fafafa;
        }

        .form-group input:focus,
        .form-group select:focus {
            outline: none;
            border-color: #4CAF50;
            background: white;
            box-shadow: 0 0 0 3px rgba(76, 175, 80, 0.1);
        }

        .form-group .hint {
            font-size: 0.85em;
            color: #999;
            margin-top: 5px;
        }

        .form-group .error {
            color: #f44336;
            font-size: 0.85em;
            margin-top: 5px;
            display: none;
        }

        .form-group.error .error {
            display: block;
        }

        .form-group.error input,
        .form-group.error select {
            border-color: #f44336;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
        }

        @media (max-width: 600px) {
            .form-row {
                grid-template-columns: 1fr;
            }
        }

        .submit-btn {
            width: 100%;
            padding: 16px;
            background: linear-gradient(135deg, #4CAF50 0%, #45a049 100%);
            color: white;
            border: none;
            border-radius: 8px;
            font-size: 1.1em;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.3s ease;
            margin-top: 20px;
            box-shadow: 0 4px 15px rgba(76, 175, 80, 0.3);
        }

        .submit-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(76, 175, 80, 0.4);
        }

        .submit-btn:active {
            transform: translateY(0);
        }

        .submit-btn:disabled {
            background: #ccc;
            cursor: not-allowed;
            transform: none;
        }

        .loading {
            display: none;
            text-align: center;
            margin-top: 20px;
        }

        .loading.show {
            display: block;
        }

        .spinner {
            border: 3px solid #f3f3f3;
            border-top: 3px solid #4CAF50;
            border-radius: 50%;
            width: 40px;
            height: 40px;
            animation: spin 1s linear infinite;
            margin: 0 auto 10px;
        }

        @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>🏥 个性化健康管理方案</h1>
            <p>请填写以下信息，我们将为您生成专属的健康管理方案</p>
        </div>

        <form id="healthForm">
            <div class="form-section">
                <h2 class="section-title">📋 基础信息</h2>

                <div class="form-row">
                    <div class="form-group">
                        <label for="age">年龄 <span style="color: red;">*</span></label>
                        <input type="number" id="age" name="age" min="10" max="100" required placeholder="请输入您的年龄">
                        <div class="hint">范围：10-100岁</div>
                        <div class="error">年龄必须在10-100之间</div>
                    </div>

                    <div class="form-group">
                        <label for="gender">性别 <span style="color: red;">*</span></label>
                        <select id="gender" name="gender" required>
                            <option value="">请选择</option>
                            <option value="男">男</option>
                            <option value="女">女</option>
                        </select>
                        <div class="error">请选择您的性别</div>
                    </div>
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label for="height">身高 (cm) <span style="color: red;">*</span></label>
                        <input type="number" id="height" name="height" min="100" max="250" required placeholder="请输入身高">
                        <div class="hint">范围：100-250cm</div>
                        <div class="error">身高必须在100-250cm之间</div>
                    </div>

                    <div class="form-group">
                        <label for="weight">体重 (kg) <span style="color: red;">*</span></label>
                        <input type="number" id="weight" name="weight" min="30" max="300" step="0.1" required placeholder="请输入当前体重">
                        <div class="hint">范围：30-300kg</div>
                        <div class="error">体重必须在30-300kg之间</div>
                    </div>
                </div>

                <div class="form-group">
                    <label for="email">邮箱地址 <span style="color: red;">*</span></label>
                    <input type="email" id="email" name="email" required placeholder="请输入您的邮箱地址">
                    <div class="hint">我们将通过此邮箱发送您的健康管理方案</div>
                    <div class="error">请输入有效的邮箱地址</div>
                </div>
            </div>

            <div class="form-section">
                <h2 class="section-title">🎯 目标设置</h2>

                <div class="form-group">
                    <label for="goalType">目标类型 <span style="color: red;">*</span></label>
                    <select id="goalType" name="goalType" required>
                        <option value="">请选择</option>
                        <option value="减肥">减肥</option>
                        <option value="增肌">增肌</option>
                        <option value="维持">维持</option>
                    </select>
                    <div class="error">请选择您的目标</div>
                </div>

                <div class="form-row">
                    <div class="form-group">
                        <label for="goalValue">目标体重 (kg) <span style="color: red;">*</span></label>
                        <input type="number" id="goalValue" name="goalValue" min="30" max="300" step="0.1" required placeholder="请输入目标体重">
                        <div class="error">请输入有效的目标体重</div>
                    </div>

                    <div class="form-group">
                        <label for="goalTime">完成时间 (周) <span style="color: red;">*</span></label>
                        <input type="number" id="goalTime" name="goalTime" min="1" max="52" required placeholder="希望在多少周内达成">
                        <div class="hint">范围：1-52周</div>
                        <div class="error">完成时间必须在1-52周之间</div>
                    </div>
                </div>

                <div class="form-group">
                    <label for="dailyTime">每日可用时间 (分钟) <span style="color: red;">*</span></label>
                    <input type="number" id="dailyTime" name="dailyTime" min="1" max="300" required placeholder="每天可用于运动的时间">
                    <div class="hint">范围：1-300分钟</div>
                    <div class="error">请输入有效的每日可用时间</div>
                </div>
            </div>

            <div class="form-section">
                <h2 class="section-title">🏠 生活条件</h2>

                <div class="form-group">
                    <label for="kitchenCondition">厨房条件 <span style="color: red;">*</span></label>
                    <select id="kitchenCondition" name="kitchenCondition" required>
                        <option value="">请选择</option>
                        <option value="自己做饭">自己做饭</option>
                        <option value="外卖为主">外卖为主</option>
                        <option value="综合">综合</option>
                    </select>
                    <div class="error">请选择您的饮食方式</div>
                </div>

                <div class="form-group">
                    <label for="facility">运动设施 <span style="color: red;">*</span></label>
                    <select id="facility" name="facility" required>
                        <option value="">请选择</option>
                        <option value="居家">居家</option>
                        <option value="健身房">健身房</option>
                        <option value="户外">户外</option>
                        <option value="综合">综合</option>
                    </select>
                    <div class="error">请选择您的运动环境</div>
                </div>

                <div class="form-group">
                    <label for="experience">运动经验 <span style="color: red;">*</span></label>
                    <select id="experience" name="experience" required>
                        <option value="">请选择</option>
                        <option value="没经验">没经验</option>
                        <option value="有经验">有经验</option>
                        <option value="经验丰富">经验丰富</option>
                    </select>
                    <div class="error">请选择您的运动经验</div>
                </div>
            </div>

            <button type="submit" class="submit-btn" id="submitBtn">
                提交信息，生成健康方案
            </button>

            <div class="loading" id="loading">
                <div class="spinner"></div>
                <p>正在提交，请稍候...</p>
            </div>
        </form>
    </div>

    <script>
        const form = document.getElementById("healthForm");
        const submitBtn = document.getElementById("submitBtn");
        const loading = document.getElementById("loading");

        // 修改：使用固定的提交URL
        const submitUrl = window.location.origin + '/webhook-test/health-form-submit';

        // 邮箱格式验证函数
        function validateEmail(email) {
            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
            return emailRegex.test(email);
        }

        function validateForm() {
            let isValid = true;
            const formGroups = form.querySelectorAll(".form-group");

            formGroups.forEach(group => {
                group.classList.remove("error");
                const input = group.querySelector("input, select");
                if (input && input.hasAttribute("required")) {
                    if (!input.value.trim()) {
                        group.classList.add("error");
                        isValid = false;
                    } else {
                        // 邮箱格式验证
                        if (input.type === "email") {
                            if (!validateEmail(input.value.trim())) {
                                group.classList.add("error");
                                group.querySelector(".error").textContent = "请输入有效的邮箱地址格式";
                                isValid = false;
                            }
                        }
                        // 数字类型验证
                        if (input.type === "number") {
                            const value = parseFloat(input.value);
                            const min = parseFloat(input.getAttribute("min"));
                            const max = parseFloat(input.getAttribute("max"));
                            if (value < min || value > max) {
                                group.classList.add("error");
                                isValid = false;
                            }
                        }
                    }
                }
            });

            const goalType = document.getElementById("goalType").value;
            const weight = parseFloat(document.getElementById("weight").value);
            const goalValue = parseFloat(document.getElementById("goalValue").value);

            if (goalType && weight && goalValue) {
                const goalGroup = document.getElementById("goalValue").closest(".form-group");
                if (goalType === "减肥" && goalValue >= weight) {
                    goalGroup.classList.add("error");
                    goalGroup.querySelector(".error").textContent = "目标体重必须小于当前体重";
                    isValid = false;
                } else if (goalType === "增肌" && goalValue <= weight) {
                    goalGroup.classList.add("error");
                    goalGroup.querySelector(".error").textContent = "目标体重必须大于当前体重";
                    isValid = false;
                }
            }

            return isValid;
        }

        form.addEventListener("submit", async (e) => {
            e.preventDefault();

            if (!validateForm()) {
                return;
            }

            submitBtn.disabled = true;
            loading.classList.add("show");

            const formData = new FormData(form);
            const data = {};
            for (const [key, value] of formData.entries()) {
                if (key === "age" || key === "height" || key === "weight" || 
                    key === "goalValue" || key === "goalTime" || key === "dailyTime") {
                    data[key] = parseFloat(value);
                } else {
                    data[key] = value.trim();
                }
            }

            try {
                // 修改：使用固定的提交URL
                const response = await fetch(submitUrl, {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json",
                    },
                    body: JSON.stringify(data)
                });

                const result = await response.json();

                if (result.success) {
                    document.body.innerHTML = result.html || "<h1>提交成功！正在处理中...</h1>";
                } else {
                    alert("提交成功！正在处理中.：" + (result.errors ? result.errors.join(", ") : result.message));
                    submitBtn.disabled = false;
                    loading.classList.remove("show");
                }
            } catch (error) {
                console.error("Error:", error);
                alert("提交成功！正在处理中.");
                submitBtn.disabled = false;
                loading.classList.remove("show");
            }
        });

        form.addEventListener("input", (e) => {
            const group = e.target.closest(".form-group");
            if (group) {
                group.classList.remove("error");
            }
        });
    </script>
</body>
</html>`;

return {
  json: {
    html: htmlForm
  }
};
